func typeBadgeClass(t string) string {
	switch typeKind(t) {
	case "num":
		return "badge-num"
	case "str":
		return "badge-str"
	case "bool":
		return "badge-bool"
	case "time":
		return "badge-time"
	default:
		return "badge-muted"
	}
}

func shortType(t string) string {
	if len(t) > 18 {
		return t[:18] + "…"
	}
	return t
}

